---
import { site } from "../site-config"

interface Props {
  title: string
}

const { title } = Astro.props
---

<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>{title}</title>
    <style>
      body {
        margin: 0;
        font: 16px/1.5 system-ui, sans-serif;
        color: #1c1c1c;
        background: #fafafa;
      }
      header,
      main,
      footer {
        max-width: 48rem;
        margin: 0 auto;
        padding: 1rem;
      }
      nav a {
        margin-right: 1rem;
      }
    </style>
  </head>
  <body>
    <header>
      {site.name && <strong>{site.name}</strong>}
      <nav>
        <a href="/">Home</a>
        <a href="/contact/">Contact</a>
      </nav>
    </header>
    <main>
      <slot />
    </main>
    <footer>
      {site.serviceArea && <p>{site.serviceArea}</p>}
    </footer>
  </body>
</html>

---
import Base from "../layouts/Base.astro"
import { site } from "../site-config"
---

<Base title={site.name || "Home"}>
  {site.name && <h1>{site.name}</h1>}
  {site.tagline && <p>{site.tagline}</p>}
  {site.standardCleanHourly && (
    <section>
      <h2>Standard clean</h2>
      <p>{site.standardCleanHourly}</p>
    </section>
  )}
  {site.weekdayHours && (
    <section>
      <h2>Hours</h2>
      <p>Weekdays {site.weekdayHours}</p>
    </section>
  )}
</Base>

---
import Base from "../layouts/Base.astro"
import { site } from "../site-config"
---

<Base title="Contact">
  <h1>Contact</h1>
  {site.phone && <p>Phone: <a href={`tel:${site.phone}`}>{site.phone}</a></p>}
  {site.email && <p>Email: <a href={`mailto:${site.email}`}>{site.email}</a></p>}
  {site.weekdayHours && <p>Weekdays {site.weekdayHours}</p>}
</Base>

